fun maximizeAnswer(low: Int, high: Int): Int {
    var left = low
    var right = high
    while (left < right) {
        val mid = left + (right - left + 1) / 2   // round UP to avoid infinite loop
        if (isFeasible(mid)) left = mid           // mid works, try larger
        else right = mid - 1                      // mid fails, need smaller
    }
    return left
}

fun minEatingSpeed(piles: IntArray, h: Int): Int {
    var left = 1
    var right = piles.max()
    while (left < right) {
        val speed = left + (right - left) / 2
        var hours = 0L
        for (p in piles) hours += (p + speed - 1) / speed    // ceil(p / speed)
        if (hours <= h) right = speed          // fast enough, try slower
        else left = speed + 1
    }
    return left
}
// Time: O(n log(max pile))   Space: O(1)

fun shipWithinDays(weights: IntArray, days: Int): Int {
    var left = weights.max()               // must carry the heaviest package
    var right = weights.sum()              // one day carries everything
    while (left < right) {
        val capacity = left + (right - left) / 2
        var daysNeeded = 1
        var load = 0
        for (w in weights) {
            if (load + w > capacity) {
                daysNeeded++               // start a new day
                load = 0
            }
            load += w
        }
        if (daysNeeded <= days) right = capacity
        else left = capacity + 1
    }
    return left
}
// Time: O(n log(sum))   Space: O(1)

fun splitArray(nums: IntArray, k: Int): Int {
    var left = nums.max()
    var right = nums.sum()
    while (left < right) {
        val maxSum = left + (right - left) / 2
        var parts = 1
        var current = 0
        for (x in nums) {
            if (current + x > maxSum) {
                parts++
                current = 0
            }
            current += x
        }
        if (parts <= k) right = maxSum     // can split into k or fewer parts
        else left = maxSum + 1
    }
    return left
}
// Time: O(n log(sum))   Space: O(1)
// Same check as ship packages: they are the same problem

fun minDays(bloomDay: IntArray, m: Int, k: Int): Int {
    if (m.toLong() * k > bloomDay.size) return -1
    var left = bloomDay.min()
    var right = bloomDay.max()
    while (left < right) {
        val day = left + (right - left) / 2
        var bouquets = 0
        var flowers = 0
        for (b in bloomDay) {
            if (b <= day) {
                flowers++
                if (flowers == k) { bouquets++; flowers = 0 }
            } else {
                flowers = 0                // adjacency broken
            }
        }
        if (bouquets >= m) right = day
        else left = day + 1
    }
    return left
}
// Time: O(n log(maxDay))   Space: O(1)

fun maxMinDistance(stalls: IntArray, cows: Int): Int {
    stalls.sort()
    var left = 1
    var right = stalls.last() - stalls.first()
    while (left < right) {
        val dist = left + (right - left + 1) / 2        // round up: maximize
        // greedy: place cows as early as possible
        var placed = 1
        var last = stalls[0]
        for (i in 1 until stalls.size) {
            if (stalls[i] - last >= dist) {
                placed++
                last = stalls[i]
            }
        }
        if (placed >= cows) left = dist                 // feasible, try larger
        else right = dist - 1
    }
    return left
}
// Time: O(n log n + n log(range))   Space: O(1)

fun maxDistance(position: IntArray, m: Int): Int {
    position.sort()
    var left = 1
    var right = position.last() - position.first()
    while (left < right) {
        val force = left + (right - left + 1) / 2
        var count = 1
        var last = position[0]
        for (i in 1 until position.size) {
            if (position[i] - last >= force) {
                count++
                last = position[i]
            }
        }
        if (count >= m) left = force
        else right = force - 1
    }
    return left
}
// Time: O(n log n + n log(range))   Space: O(1)

fun smallestDivisor(nums: IntArray, threshold: Int): Int {
    var left = 1
    var right = nums.max()
    while (left < right) {
        val d = left + (right - left) / 2
        var sum = 0L
        for (x in nums) sum += (x + d - 1) / d          // ceil(x / d)
        if (sum <= threshold) right = d
        else left = d + 1
    }
    return left
}
// Time: O(n log(max))   Space: O(1)

fun nthRoot(x: Double, n: Int): Double {
    var low = 0.0
    var high = maxOf(1.0, x)
    repeat(100) {                                        // fixed iterations for doubles
        val mid = (low + high) / 2
        if (Math.pow(mid, n.toDouble()) < x) low = mid
        else high = mid
    }
    return low
}
// Time: O(100 * n)   Space: O(1)
// With doubles use a fixed number of iterations, not left < right

fun kthSmallest(matrix: Array<IntArray>, k: Int): Int {
    val n = matrix.size
    var left = matrix[0][0]
    var right = matrix[n - 1][n - 1]
    while (left < right) {
        val mid = left + (right - left) / 2
        // count elements <= mid by walking from the bottom-left corner
        var count = 0
        var row = n - 1
        var col = 0
        while (row >= 0 && col < n) {
            if (matrix[row][col] <= mid) {
                count += row + 1
                col++
            } else {
                row--
            }
        }
        if (count >= k) right = mid
        else left = mid + 1
    }
    return left
}
// Time: O(n log(max - min))   Space: O(1)

fun findMedianSortedArrays(a: IntArray, b: IntArray): Double {
    if (a.size > b.size) return findMedianSortedArrays(b, a)
    val m = a.size
    val n = b.size
    var low = 0
    var high = m
    while (low <= high) {
        val i = (low + high) / 2                    // elements taken from a
        val j = (m + n + 1) / 2 - i                 // elements taken from b
        val aLeft = if (i == 0) Int.MIN_VALUE else a[i - 1]
        val aRight = if (i == m) Int.MAX_VALUE else a[i]
        val bLeft = if (j == 0) Int.MIN_VALUE else b[j - 1]
        val bRight = if (j == n) Int.MAX_VALUE else b[j]
        if (aLeft <= bRight && bLeft <= aRight) {
            return if ((m + n) % 2 == 1) maxOf(aLeft, bLeft).toDouble()
            else (maxOf(aLeft, bLeft) + minOf(aRight, bRight)) / 2.0
        }
        if (aLeft > bRight) high = i - 1 else low = i + 1
    }
    return 0.0
}
// Time: O(log(min(m, n)))   Space: O(1)
